def main(video_url):
    if "douyin" in video_url or "v.douyin" in video_url:
        platform = "douyin"
    elif "kuaishou" in video_url or "ks" in video_url:
        platform = "kuaishou"
    elif "bilibili" in video_url or "bilibili.com" in video_url:
        platform = "bilibili"
    else:
        platform = "unknown"
    return {"platform": platform, "video_url": video_url}

def main(platform, video_url):
    platforms = {"douyin": "抖音", "kuaishou": "快手", "bilibili": "B站"}
    result = {
        "platform": platforms.get(platform, platform),
        "video_url": video_url,
        "extracted_text": "从视频中提取的文案内容...",
        "video_info": {"title": "视频标题", "duration": 120}
    }
    return result
